<?php
namespace App\Services;
use App\Models\CommercialDocument;use App\Models\Payment;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class PaymentService{public function __construct(private readonly AccountingPostingService $accounting){}public function create(array $data):Payment{return DB::transaction(function()use($data){$number='PAY-'.now()->format('ym').'-'.str_pad((string)((int)Payment::where('shop_id',session('active_shop_id'))->lockForUpdate()->max('id')+1),5,'0',STR_PAD_LEFT);$payment=Payment::create($data+['shop_id'=>session('active_shop_id'),'godown_id'=>session('active_godown_id'),'number'=>$number,'created_by'=>auth()->id()]);if($payment->commercial_document_id){$document=CommercialDocument::lockForUpdate()->findOrFail($payment->commercial_document_id);abort_unless($document->shop_id===(int)session('active_shop_id'),404);$paid=(float)$document->paid_amount+(float)$payment->amount;if($paid>(float)$document->total_amount)throw ValidationException::withMessages(['amount'=>'Payment exceeds the document balance.']);$document->update(['paid_amount'=>$paid,'balance_amount'=>(float)$document->total_amount-$paid]);}$payment->load(['party','document','method']);$this->accounting->postPayment($payment);return $payment;});}}
